#include <vector>

using namespace std;

class Solution {
public:
    int minSwaps(vector<vector<int>>& grid) {
        int n = grid.size(), res = 0;
        vector<int> zeros(n);
        for (int i = 0; i < n; ++i) {
            int z = 0;
            for (int j = n - 1; j >= 0 && grid[i][j] == 0; --j) z++;
            zeros[i] = z;
        }

        for (int i = 0; i < n; ++i) {
            int need = n - 1 - i;
            int j = i;
            while (j < n && zeros[j] < need) j++;
            if (j == n) return -1;
            while (j > i) {
                swap(zeros[j], zeros[j - 1]);
                res++;
                j--;
            }
        }

        return res;
    }
};
